"use client";

import { useState } from "react";
import { Search, CheckCircle2, AlertCircle, Car, MapPin, Calendar, Clock } from "lucide-react";

const API_BASE = process.env.NEXT_PUBLIC_API_URL || "http://localhost:5000/api";

// Fallback sample slots so the UI works immediately even before the backend is running
const DEMO_SLOTS = [
  { id: "slot-a1", slot_number: "A-01", is_active: true },
  { id: "slot-a2", slot_number: "A-02", is_active: true },
  { id: "slot-a3", slot_number: "A-03", is_active: true },
  { id: "slot-b1", slot_number: "B-01", is_active: true },
  { id: "slot-b2", slot_number: "B-02", is_active: true },
  { id: "slot-b3", slot_number: "B-03", is_active: true },
];

export default function Home() {
  const [startTime, setStartTime] = useState("");
  const [endTime, setEndTime] = useState("");
  const [slots, setSlots] = useState([]);
  const [selectedSlot, setSelectedSlot] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [booking, setBooking] = useState(null);

  const handleSearch = async (e) => {
    e.preventDefault();
    if (!startTime || !endTime) {
      setError("Please select both a start time and an end time.");
      return;
    }

    if (new Date(endTime) <= new Date(startTime)) {
      setError("End time must be after start time.");
      return;
    }

    setError("");
    setLoading(true);

    try {
      const res = await fetch(
        `${API_BASE}/slots/available?locationId=11111111-1111-1111-1111-111111111111&startTime=${new Date(
          startTime
        ).toISOString()}&endTime=${new Date(endTime).toISOString()}`
      );

      if (!res.ok) throw new Error("Backend offline, switching to demo slots");
      const data = await res.json();
      setSlots(data.length > 0 ? data : DEMO_SLOTS);
    } catch {
      // Fallback to sample slots for preview
      setSlots(DEMO_SLOTS);
    } finally {
      setLoading(false);
    }
  };

  const handleConfirmReservation = async () => {
    if (!selectedSlot) return;
    setLoading(true);
    setError("");

    try {
      const res = await fetch(`${API_BASE}/bookings`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          userId: "00000000-0000-0000-0000-000000000001",
          slotId: selectedSlot.id,
          startTime: new Date(startTime).toISOString(),
          endTime: new Date(endTime).toISOString(),
          totalAmount: 15.0,
        }),
      });

      if (!res.ok) throw new Error("Backend offline, generating demo confirmation");
      const data = await res.json();
      setBooking(data);
    } catch {
      // Demo confirmation QR placeholder
      setBooking({
        booking: { id: "DEMO-PARKEASE-" + Math.floor(1000 + Math.random() * 9000) },
        qrCode: `https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(
          JSON.stringify({
            slot: selectedSlot.slot_number,
            start: startTime,
            end: endTime,
          })
        )}`,
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 py-10 px-4 sm:px-6">
      <div className="max-w-4xl mx-auto space-y-8">

        {/* Header Banner */}
        <div className="bg-indigo-600 rounded-2xl p-6 sm:p-8 text-white shadow-lg shadow-indigo-100 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
          <div>
            <div className="inline-flex items-center gap-2 bg-indigo-500/50 px-3 py-1 rounded-full text-xs font-semibold uppercase tracking-wider text-indigo-100 mb-2">
              <Car className="w-3.5 h-3.5" /> Smart Parking Management
            </div>
            <h1 className="text-3xl font-bold tracking-tight">Reserve Your Parking Slot</h1>
            <p className="text-indigo-100 text-sm mt-1">
              Select your schedule to view live slot availability and get instant entry pass.
            </p>
          </div>
          <div className="flex items-center gap-2 bg-white/10 px-4 py-2.5 rounded-xl border border-white/20 text-xs">
            <MapPin className="w-4 h-4 text-indigo-200" />
            <span>Central Campus Lot A</span>
          </div>
        </div>

        {/* Error Alert */}
        {error && (
          <div className="flex items-center gap-2 p-4 bg-red-50 border border-red-200 text-red-700 rounded-xl text-sm">
            <AlertCircle className="w-5 h-5 shrink-0" />
            <span>{error}</span>
          </div>
        )}

        {/* Booking Duration Form */}
        <form
          onSubmit={handleSearch}
          className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm grid grid-cols-1 md:grid-cols-3 gap-4"
        >
          <div>
            <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1.5 flex items-center gap-1.5">
              <Calendar className="w-3.5 h-3.5 text-indigo-600" /> Start Time
            </label>
            <input
              type="datetime-local"
              value={startTime}
              onChange={(e) => setStartTime(e.target.value)}
              className="w-full border border-slate-300 rounded-lg p-2.5 text-sm bg-slate-50 focus:bg-white focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition"
              required
            />
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1.5 flex items-center gap-1.5">
              <Clock className="w-3.5 h-3.5 text-indigo-600" /> End Time
            </label>
            <input
              type="datetime-local"
              value={endTime}
              onChange={(e) => setEndTime(e.target.value)}
              className="w-full border border-slate-300 rounded-lg p-2.5 text-sm bg-slate-50 focus:bg-white focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition"
              required
            />
          </div>

          <div className="flex items-end">
            <button
              type="submit"
              disabled={loading}
              className="w-full bg-indigo-600 hover:bg-indigo-700 text-white font-medium py-2.5 px-4 rounded-lg flex items-center justify-center gap-2 transition disabled:opacity-50 shadow-sm"
            >
              <Search className="w-4 h-4" />
              {loading ? "Searching..." : "Find Available Slots"}
            </button>
          </div>
        </form>

        {/* Available Slots Section */}
        {slots.length > 0 && !booking && (
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
            <div className="flex items-center justify-between mb-4">
              <div>
                <h2 className="text-lg font-bold text-slate-800">Available Parking Slots</h2>
                <p className="text-xs text-slate-500">Pick an empty spot to lock in your reservation.</p>
              </div>
              <span className="text-xs font-medium bg-emerald-50 text-emerald-700 px-2.5 py-1 rounded-full border border-emerald-200">
                {slots.length} Available
              </span>
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-6 gap-3">
              {slots.map((slot) => {
                const isSelected = selectedSlot?.id === slot.id;
                return (
                  <button
                    key={slot.id}
                    type="button"
                    onClick={() => setSelectedSlot(slot)}
                    className={`p-4 rounded-xl border text-center font-bold text-lg transition flex flex-col items-center justify-center gap-1 ${isSelected
                        ? "bg-indigo-600 text-white border-indigo-600 shadow-md ring-2 ring-indigo-400"
                        : "bg-slate-50 border-slate-200 text-slate-700 hover:border-indigo-400 hover:bg-white"
                      }`}
                  >
                    <Car className={`w-5 h-5 ${isSelected ? "text-white" : "text-slate-400"}`} />
                    <span>{slot.slot_number}</span>
                  </button>
                );
              })}
            </div>

            <div className="mt-6 flex flex-col sm:flex-row items-center justify-between gap-4 border-t border-slate-100 pt-5">
              <div className="text-sm text-slate-600">
                {selectedSlot ? (
                  <span>Selected: <strong className="text-slate-900">{selectedSlot.slot_number}</strong> ($15.00 flat)</span>
                ) : (
                  <span>Please select a slot above.</span>
                )}
              </div>
              <button
                type="button"
                onClick={handleConfirmReservation}
                disabled={!selectedSlot || loading}
                className="w-full sm:w-auto bg-emerald-600 hover:bg-emerald-700 text-white font-medium py-2.5 px-6 rounded-lg transition disabled:opacity-50 shadow-sm"
              >
                {loading ? "Processing..." : `Confirm Booking`}
              </button>
            </div>
          </div>
        )}

        {/* QR Confirmation Card */}
        {booking && (
          <div className="bg-white p-8 rounded-2xl border border-emerald-200 shadow-md text-center max-w-md mx-auto space-y-4">
            <div className="w-14 h-14 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto">
              <CheckCircle2 className="w-8 h-8" />
            </div>
            <div>
              <h2 className="text-2xl font-bold text-slate-800">Booking Confirmed!</h2>
              <p className="text-sm text-slate-500 mt-1">
                Scan this QR code at the entry barrier.
              </p>
            </div>

            <div className="p-3 bg-slate-50 rounded-xl border border-slate-200 inline-block">
              <img
                src={booking.qrCode}
                alt="Entry QR Code"
                className="w-48 h-48 mx-auto rounded-lg bg-white"
              />
            </div>

            <div className="bg-slate-100 text-slate-600 font-mono text-xs py-2 px-3 rounded-lg">
              Pass ID: {booking.booking.id}
            </div>

            <button
              onClick={() => {
                setBooking(null);
                setSelectedSlot(null);
              }}
              className="text-xs text-indigo-600 hover:text-indigo-800 underline font-medium block mx-auto pt-2"
            >
              Make another reservation
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
